-- ============================================================
-- 企业采购询价比价与审批管理系统 数据库初始化脚本
-- MySQL 8.0 / utf8mb4 / 库名 new_006
-- 说明：包含建库、建表、索引、字典、角色菜单与真实分布测试数据
-- 测试图片均为项目内本地文件（uploads/seed/...），无任何外链
-- ============================================================
DROP DATABASE IF EXISTS `new_006`;
CREATE DATABASE `new_006` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_006`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 组织 ----------
CREATE TABLE sys_org (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  org_name VARCHAR(64) NOT NULL COMMENT '组织名称',
  org_code VARCHAR(32) NOT NULL COMMENT '组织编码',
  parent_id BIGINT DEFAULT 0 COMMENT '上级组织',
  leader VARCHAR(32) DEFAULT NULL COMMENT '负责人',
  sort INT DEFAULT 0 COMMENT '排序',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB COMMENT='组织架构';

-- ---------- 角色 ----------
CREATE TABLE sys_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  role_name VARCHAR(64) NOT NULL COMMENT '角色名称',
  role_code VARCHAR(32) NOT NULL COMMENT '角色编码',
  data_scope VARCHAR(20) NOT NULL DEFAULT 'SELF' COMMENT '数据范围 SELF/DEPT/ORG/ALL',
  remark VARCHAR(200) DEFAULT NULL COMMENT '说明',
  status TINYINT DEFAULT 1 COMMENT '1启用 0停用',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_role_code (role_code)
) ENGINE=InnoDB COMMENT='角色';

-- ---------- 用户 ----------
CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  username VARCHAR(50) NOT NULL COMMENT '登录账号',
  password VARCHAR(100) NOT NULL COMMENT 'BCrypt 密码',
  real_name VARCHAR(50) NOT NULL COMMENT '姓名',
  avatar VARCHAR(200) DEFAULT NULL COMMENT '头像相对路径',
  phone VARCHAR(20) DEFAULT NULL COMMENT '手机号',
  email VARCHAR(80) DEFAULT NULL COMMENT '邮箱',
  org_id BIGINT DEFAULT NULL COMMENT '所属组织',
  role_id BIGINT DEFAULT NULL COMMENT '角色',
  status TINYINT DEFAULT 1 COMMENT '1启用 0停用',
  login_fail INT DEFAULT 0 COMMENT '连续登录失败次数',
  lock_until DATETIME DEFAULT NULL COMMENT '锁定截止时间',
  last_login DATETIME DEFAULT NULL COMMENT '最后登录',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  deleted TINYINT DEFAULT 0 COMMENT '逻辑删除',
  UNIQUE KEY uk_username (username),
  KEY idx_user_org (org_id)
) ENGINE=InnoDB COMMENT='用户';

-- ---------- 菜单 ----------
CREATE TABLE sys_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  parent_id BIGINT DEFAULT 0 COMMENT '上级菜单',
  menu_name VARCHAR(64) NOT NULL COMMENT '菜单名称',
  menu_type CHAR(1) NOT NULL COMMENT 'M目录 C菜单 B按钮',
  path VARCHAR(120) DEFAULT NULL COMMENT '路由',
  perm VARCHAR(80) DEFAULT NULL COMMENT '权限标识',
  icon VARCHAR(40) DEFAULT NULL COMMENT '图标',
  sort INT DEFAULT 0 COMMENT '排序',
  visible TINYINT DEFAULT 1 COMMENT '1显示 0隐藏',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB COMMENT='菜单与按钮权限';

CREATE TABLE sys_role_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_id BIGINT NOT NULL COMMENT '角色',
  menu_id BIGINT NOT NULL COMMENT '菜单',
  KEY idx_rm_role (role_id)
) ENGINE=InnoDB COMMENT='角色菜单';

-- ---------- 字典 ----------
CREATE TABLE sys_dict (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  dict_type VARCHAR(40) NOT NULL COMMENT '字典类型',
  dict_label VARCHAR(60) NOT NULL COMMENT '标签',
  dict_value VARCHAR(40) NOT NULL COMMENT '值',
  sort INT DEFAULT 0,
  status TINYINT DEFAULT 1,
  KEY idx_dict_type (dict_type)
) ENGINE=InnoDB COMMENT='数据字典';

-- ---------- 消息 ----------
CREATE TABLE sys_message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  title VARCHAR(200) NOT NULL COMMENT '标题',
  content VARCHAR(500) DEFAULT NULL COMMENT '内容',
  biz_type VARCHAR(30) DEFAULT NULL COMMENT '业务类型 REQUEST/INQUIRY/ORDER/RECEIPT',
  biz_no VARCHAR(50) DEFAULT NULL COMMENT '业务编号',
  biz_id BIGINT DEFAULT NULL COMMENT '业务主键，用于跳转',
  receiver_id BIGINT NOT NULL COMMENT '接收人',
  is_read TINYINT DEFAULT 0 COMMENT '0未读 1已读',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_msg_receiver (receiver_id, is_read)
) ENGINE=InnoDB COMMENT='站内消息';

-- ---------- 操作日志 ----------
CREATE TABLE sys_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT DEFAULT NULL,
  user_name VARCHAR(50) DEFAULT NULL,
  module VARCHAR(40) DEFAULT NULL COMMENT '模块',
  action VARCHAR(40) DEFAULT NULL COMMENT '动作',
  biz_no VARCHAR(50) DEFAULT NULL COMMENT '业务编号',
  detail VARCHAR(300) DEFAULT NULL COMMENT '说明',
  ip VARCHAR(40) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_log_time (create_time)
) ENGINE=InnoDB COMMENT='操作日志';

-- ---------- 物料分类与物料 ----------
CREATE TABLE material_category (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  cat_name VARCHAR(60) NOT NULL COMMENT '分类名称',
  cat_code VARCHAR(30) NOT NULL COMMENT '分类编码',
  sort INT DEFAULT 0,
  status TINYINT DEFAULT 1,
  UNIQUE KEY uk_cat_code (cat_code)
) ENGINE=InnoDB COMMENT='物料分类';

CREATE TABLE material (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  material_code VARCHAR(40) NOT NULL COMMENT '物料编码',
  material_name VARCHAR(80) NOT NULL COMMENT '物料名称',
  spec VARCHAR(120) NOT NULL COMMENT '规格参数',
  unit VARCHAR(10) NOT NULL COMMENT '单位',
  category_id BIGINT NOT NULL COMMENT '分类',
  ref_price DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '参考价',
  image VARCHAR(200) DEFAULT NULL COMMENT '图片相对路径',
  status TINYINT DEFAULT 1 COMMENT '1启用 0停用',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_material_code (material_code),
  KEY idx_material_cat (category_id)
) ENGINE=InnoDB COMMENT='物料主数据';

-- ---------- 供应商 ----------
CREATE TABLE supplier (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  supplier_name VARCHAR(100) NOT NULL COMMENT '供应商名称',
  credit_code VARCHAR(40) NOT NULL COMMENT '统一社会信用代码',
  category VARCHAR(60) DEFAULT NULL COMMENT '主营品类',
  contact VARCHAR(40) DEFAULT NULL COMMENT '联系人',
  phone VARCHAR(20) DEFAULT NULL,
  address VARCHAR(200) DEFAULT NULL,
  rating VARCHAR(8) DEFAULT 'B' COMMENT '评级',
  quality_score DECIMAL(5,2) DEFAULT 70 COMMENT '历史质量评分',
  on_time_rate DECIMAL(5,2) DEFAULT 80 COMMENT '历史准时率(%)',
  after_sales_score DECIMAL(5,2) DEFAULT 70 COMMENT '售后评分',
  payment_term VARCHAR(30) DEFAULT '月结 30 天' COMMENT '默认付款条件',
  status VARCHAR(20) DEFAULT 'QUALIFIED' COMMENT 'QUALIFIED/OBSERVE/DISABLED',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_supplier_credit (credit_code)
) ENGINE=InnoDB COMMENT='供应商档案';

-- ---------- 采购需求 ----------
CREATE TABLE purchase_request (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  request_no VARCHAR(50) NOT NULL COMMENT '需求编号',
  title VARCHAR(120) NOT NULL COMMENT '需求标题',
  org_id BIGINT NOT NULL COMMENT '申请部门',
  applicant_id BIGINT NOT NULL COMMENT '申请人',
  category_id BIGINT DEFAULT NULL COMMENT '物料分类',
  budget_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '预算金额',
  expect_date DATE DEFAULT NULL COMMENT '期望到货日',
  urgency VARCHAR(10) DEFAULT 'NORMAL' COMMENT 'URGENT/NORMAL/LOW',
  purpose VARCHAR(300) DEFAULT NULL COMMENT '用途说明',
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/DEPT_PENDING/REJECTED/PURCHASING/QUOTED/COMPLETED/CANCELLED',
  current_handler VARCHAR(50) DEFAULT NULL COMMENT '当前处理人',
  reject_reason VARCHAR(300) DEFAULT NULL COMMENT '退回原因',
  submit_time DATETIME DEFAULT NULL COMMENT '提交时间',
  version INT DEFAULT 0 COMMENT '乐观锁版本',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_request_no (request_no),
  KEY idx_req_status (status),
  KEY idx_req_org (org_id)
) ENGINE=InnoDB COMMENT='采购需求主档';

CREATE TABLE request_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  request_id BIGINT NOT NULL COMMENT '需求',
  material_id BIGINT DEFAULT NULL COMMENT '物料',
  material_name VARCHAR(80) NOT NULL COMMENT '物料名称快照',
  spec VARCHAR(120) DEFAULT NULL COMMENT '规格快照',
  unit VARCHAR(10) DEFAULT '件',
  quantity DECIMAL(12,2) NOT NULL DEFAULT 0,
  budget_price DECIMAL(14,2) DEFAULT 0 COMMENT '预算单价',
  remark VARCHAR(200) DEFAULT NULL,
  KEY idx_ri_request (request_id)
) ENGINE=InnoDB COMMENT='采购需求明细';

-- ---------- 询价 ----------
CREATE TABLE inquiry (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_no VARCHAR(50) NOT NULL COMMENT '询价单号',
  title VARCHAR(120) NOT NULL COMMENT '标题',
  buyer_id BIGINT NOT NULL COMMENT '采购专员',
  request_ids VARCHAR(120) DEFAULT NULL COMMENT '关联需求ID，逗号分隔',
  budget_amount DECIMAL(14,2) DEFAULT 0 COMMENT '预算金额',
  deadline DATETIME DEFAULT NULL COMMENT '报价截止时间',
  tax_rate DECIMAL(5,2) DEFAULT 13.00 COMMENT '税率',
  delivery_req VARCHAR(200) DEFAULT NULL COMMENT '交货要求',
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/QUOTING/COMPARING/APPROVING/AWARDED/VOID',
  rule_id BIGINT DEFAULT NULL COMMENT '启用规则版本',
  rule_version VARCHAR(10) DEFAULT NULL,
  award_reason VARCHAR(300) DEFAULT NULL COMMENT '定标说明/偏离原因',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  version INT DEFAULT 0,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_inquiry_no (inquiry_no),
  KEY idx_inq_status (status)
) ENGINE=InnoDB COMMENT='询价比价单';

CREATE TABLE inquiry_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_id BIGINT NOT NULL COMMENT '询价单',
  request_item_id BIGINT DEFAULT NULL COMMENT '来源需求明细',
  material_name VARCHAR(80) NOT NULL,
  spec VARCHAR(120) DEFAULT NULL,
  unit VARCHAR(10) DEFAULT '件',
  quantity DECIMAL(12,2) NOT NULL DEFAULT 0,
  KEY idx_ii_inquiry (inquiry_id)
) ENGINE=InnoDB COMMENT='询价明细';

CREATE TABLE inquiry_supplier (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_id BIGINT NOT NULL,
  supplier_id BIGINT NOT NULL,
  invited_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '邀约时间',
  quote_status VARCHAR(20) DEFAULT 'PENDING' COMMENT 'PENDING/SUBMITTED',
  KEY idx_is_inquiry (inquiry_id)
) ENGINE=InnoDB COMMENT='询价邀约供应商';

CREATE TABLE supplier_quote (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_id BIGINT NOT NULL,
  supplier_id BIGINT NOT NULL,
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '含税总价',
  tax_amount DECIMAL(14,2) DEFAULT 0 COMMENT '税额',
  delivery_days INT DEFAULT 0 COMMENT '交付天数',
  payment_term VARCHAR(30) DEFAULT NULL COMMENT '付款条件',
  warranty_months INT DEFAULT 12 COMMENT '质保月数',
  remark VARCHAR(300) DEFAULT NULL,
  attachment VARCHAR(200) DEFAULT NULL COMMENT '报价附件相对路径',
  status VARCHAR(20) DEFAULT 'SUBMITTED' COMMENT 'PENDING/SUBMITTED/LOCKED/INVALID',
  quote_time DATETIME DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_sq_inquiry (inquiry_id),
  KEY idx_sq_supplier (supplier_id)
) ENGINE=InnoDB COMMENT='供应商报价';

CREATE TABLE quote_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  quote_id BIGINT NOT NULL,
  inquiry_item_id BIGINT NOT NULL,
  unit_price DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '含税单价',
  quantity DECIMAL(12,2) NOT NULL DEFAULT 0,
  amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '小计',
  KEY idx_qi_quote (quote_id)
) ENGINE=InnoDB COMMENT='报价明细';

-- ---------- 比价与定标 ----------
CREATE TABLE comparison_result (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_id BIGINT NOT NULL,
  supplier_id BIGINT NOT NULL,
  price_score DECIMAL(6,2) DEFAULT 0 COMMENT '价格得分',
  delivery_score DECIMAL(6,2) DEFAULT 0,
  quality_score DECIMAL(6,2) DEFAULT 0,
  ontime_score DECIMAL(6,2) DEFAULT 0,
  payment_score DECIMAL(6,2) DEFAULT 0,
  after_sales_score DECIMAL(6,2) DEFAULT 0,
  total_score DECIMAL(6,2) DEFAULT 0 COMMENT '综合得分',
  grade VARCHAR(10) DEFAULT NULL COMMENT '推荐/可选/不推荐',
  recommend TINYINT DEFAULT 0 COMMENT '1为推荐方案',
  rule_version VARCHAR(10) DEFAULT NULL,
  calc_time DATETIME DEFAULT NULL,
  KEY idx_cr_inquiry (inquiry_id)
) ENGINE=InnoDB COMMENT='比价结果（每供应商一行）';

CREATE TABLE rule_config (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  version VARCHAR(10) NOT NULL COMMENT '规则版本',
  price_weight DECIMAL(5,2) NOT NULL DEFAULT 35,
  delivery_weight DECIMAL(5,2) NOT NULL DEFAULT 15,
  quality_weight DECIMAL(5,2) NOT NULL DEFAULT 20,
  ontime_weight DECIMAL(5,2) NOT NULL DEFAULT 15,
  payment_weight DECIMAL(5,2) NOT NULL DEFAULT 10,
  after_sales_weight DECIMAL(5,2) NOT NULL DEFAULT 5,
  recommend_threshold DECIMAL(5,2) DEFAULT 80,
  optional_threshold DECIMAL(5,2) DEFAULT 70,
  status TINYINT DEFAULT 1 COMMENT '1生效 0归档',
  effect_time DATETIME DEFAULT NULL,
  create_by VARCHAR(50) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_rule_version (version)
) ENGINE=InnoDB COMMENT='综合比价规则配置（创新点）';

CREATE TABLE score_snapshot (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  inquiry_id BIGINT NOT NULL,
  rule_id BIGINT NOT NULL,
  rule_version VARCHAR(10) NOT NULL,
  input_json TEXT COMMENT '输入快照',
  detail_json TEXT COMMENT '各项得分与解释',
  total_score DECIMAL(6,2) DEFAULT 0,
  grade VARCHAR(10) DEFAULT NULL,
  recommend_supplier_id BIGINT DEFAULT NULL,
  recommend_supplier_name VARCHAR(100) DEFAULT NULL,
  calc_time DATETIME DEFAULT NULL,
  adjust_result VARCHAR(100) DEFAULT NULL COMMENT '人工调整结果',
  adjust_reason VARCHAR(300) DEFAULT NULL COMMENT '人工调整原因（≥5字）',
  adjust_by VARCHAR(50) DEFAULT NULL,
  adjust_time DATETIME DEFAULT NULL,
  KEY idx_ss_inquiry (inquiry_id)
) ENGINE=InnoDB COMMENT='综合比价计算快照与人工修正（创新点）';

-- ---------- 采购单 ----------
CREATE TABLE purchase_order (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_no VARCHAR(50) NOT NULL COMMENT '采购单号',
  inquiry_id BIGINT DEFAULT NULL,
  supplier_id BIGINT NOT NULL,
  total_amount DECIMAL(14,2) DEFAULT 0 COMMENT '含税金额',
  tax_amount DECIMAL(14,2) DEFAULT 0 COMMENT '税额',
  delivery_date DATE DEFAULT NULL,
  contact VARCHAR(40) DEFAULT NULL,
  contact_phone VARCHAR(20) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'PENDING' COMMENT 'PENDING/EXECUTING/PARTIAL/PENDING_CLOSE/COMPLETED',
  close_time DATETIME DEFAULT NULL,
  create_by BIGINT DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  version INT DEFAULT 0,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_order_no (order_no),
  KEY idx_po_status (status),
  KEY idx_po_supplier (supplier_id)
) ENGINE=InnoDB COMMENT='采购单';

CREATE TABLE purchase_order_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_id BIGINT NOT NULL,
  material_name VARCHAR(80) NOT NULL,
  spec VARCHAR(120) DEFAULT NULL,
  unit VARCHAR(10) DEFAULT '件',
  quantity DECIMAL(12,2) NOT NULL DEFAULT 0,
  unit_price DECIMAL(14,2) NOT NULL DEFAULT 0,
  amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  received_qty DECIMAL(12,2) DEFAULT 0 COMMENT '累计到货',
  qualified_qty DECIMAL(12,2) DEFAULT 0 COMMENT '累计合格',
  unqualified_qty DECIMAL(12,2) DEFAULT 0 COMMENT '累计不合格',
  KEY idx_poi_order (order_id)
) ENGINE=InnoDB COMMENT='采购单明细';

-- ---------- 验收与退货 ----------
CREATE TABLE receipt_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  receipt_no VARCHAR(50) NOT NULL COMMENT '验收单号',
  order_id BIGINT NOT NULL,
  batch_no VARCHAR(20) DEFAULT '第 1 批',
  receipt_date DATE DEFAULT NULL,
  conclusion VARCHAR(20) DEFAULT 'QUALIFIED' COMMENT 'QUALIFIED/PARTIAL/UNQUALIFIED',
  remark VARCHAR(300) DEFAULT NULL,
  images VARCHAR(300) DEFAULT NULL COMMENT '验收图片相对路径，逗号分隔',
  receiver_id BIGINT DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_receipt_no (receipt_no),
  KEY idx_rr_order (order_id)
) ENGINE=InnoDB COMMENT='到货验收单';

CREATE TABLE receipt_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  receipt_id BIGINT NOT NULL,
  order_item_id BIGINT NOT NULL,
  arrival_qty DECIMAL(12,2) DEFAULT 0,
  qualified_qty DECIMAL(12,2) DEFAULT 0,
  unqualified_qty DECIMAL(12,2) DEFAULT 0,
  reason VARCHAR(200) DEFAULT NULL COMMENT '不合格原因',
  KEY idx_rit_receipt (receipt_id)
) ENGINE=InnoDB COMMENT='验收明细';

CREATE TABLE return_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  return_no VARCHAR(50) NOT NULL,
  order_id BIGINT NOT NULL,
  order_item_id BIGINT NOT NULL,
  supplier_id BIGINT NOT NULL,
  quantity DECIMAL(12,2) DEFAULT 0,
  reason VARCHAR(200) DEFAULT NULL,
  handle_type VARCHAR(20) DEFAULT 'EXCHANGE' COMMENT 'EXCHANGE/REFUND',
  status VARCHAR(20) DEFAULT 'WAIT_SUPPLIER' COMMENT 'WAIT_SUPPLIER/EXCHANGING/CLOSED',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_return_no (return_no),
  KEY idx_rt_order (order_id)
) ENGINE=InnoDB COMMENT='退货记录';

-- ---------- 流转记录 / 附件 ----------
CREATE TABLE flow_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(20) NOT NULL COMMENT 'REQUEST/INQUIRY/ORDER/RECEIPT',
  biz_id BIGINT NOT NULL,
  biz_no VARCHAR(50) DEFAULT NULL,
  from_status VARCHAR(20) DEFAULT NULL,
  to_status VARCHAR(20) DEFAULT NULL,
  action VARCHAR(40) DEFAULT NULL COMMENT '动作',
  reason VARCHAR(300) DEFAULT NULL COMMENT '原因（退回/取消/偏离必填）',
  operator_id BIGINT DEFAULT NULL,
  operator_name VARCHAR(50) DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_fl_biz (biz_type, biz_id)
) ENGINE=InnoDB COMMENT='业务流转与操作时间轴';

CREATE TABLE attachment (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(20) NOT NULL,
  biz_id BIGINT NOT NULL,
  file_name VARCHAR(200) NOT NULL COMMENT '原始文件名',
  file_path VARCHAR(200) NOT NULL COMMENT '相对路径',
  file_size BIGINT DEFAULT 0,
  uploader_id BIGINT DEFAULT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_att_biz (biz_type, biz_id)
) ENGINE=InnoDB COMMENT='附件元数据';

SET FOREIGN_KEY_CHECKS = 1;
