-- 采购单状态与到货进度对齐（全部到货且无不合格 → 待结单/已完成）
UPDATE purchase_order o SET o.status='PARTIAL'
WHERE o.status='EXECUTING' AND EXISTS (SELECT 1 FROM purchase_order_item i WHERE i.order_id=o.id AND i.received_qty>0);
UPDATE purchase_order o SET o.status='PENDING_CLOSE'
WHERE o.status='PARTIAL' AND NOT EXISTS (SELECT 1 FROM purchase_order_item i WHERE i.order_id=o.id AND i.received_qty < i.quantity);
UPDATE purchase_order o SET o.status='COMPLETED', o.close_time=DATE_ADD(o.delivery_date, INTERVAL 10 DAY)
WHERE o.status IN ('PENDING_CLOSE') AND o.id % 2 = 0;
