-- ================= 校验 =================
SELECT '组织' AS 表名, COUNT(*) AS 行数 FROM sys_org
UNION ALL SELECT '用户', COUNT(*) FROM sys_user
UNION ALL SELECT '菜单', COUNT(*) FROM sys_menu
UNION ALL SELECT '角色菜单', COUNT(*) FROM sys_role_menu
UNION ALL SELECT '物料', COUNT(*) FROM material
UNION ALL SELECT '供应商', COUNT(*) FROM supplier
UNION ALL SELECT '采购需求', COUNT(*) FROM purchase_request
UNION ALL SELECT '需求明细', COUNT(*) FROM request_item
UNION ALL SELECT '询价单', COUNT(*) FROM inquiry
UNION ALL SELECT '询价明细', COUNT(*) FROM inquiry_item
UNION ALL SELECT '供应商报价', COUNT(*) FROM supplier_quote
UNION ALL SELECT '报价明细', COUNT(*) FROM quote_item
UNION ALL SELECT '比价结果', COUNT(*) FROM comparison_result
UNION ALL SELECT '计算快照', COUNT(*) FROM score_snapshot
UNION ALL SELECT '采购单', COUNT(*) FROM purchase_order
UNION ALL SELECT '采购明细', COUNT(*) FROM purchase_order_item
UNION ALL SELECT '验收单', COUNT(*) FROM receipt_record
UNION ALL SELECT '验收明细', COUNT(*) FROM receipt_item
UNION ALL SELECT '退货单', COUNT(*) FROM return_record
UNION ALL SELECT '流转记录', COUNT(*) FROM flow_log
UNION ALL SELECT '消息', COUNT(*) FROM sys_message
UNION ALL SELECT '日志', COUNT(*) FROM sys_log;
